let aea1CurrentSession='s1', aea1CurrentPhase='mission';
function renderAea1Hybrid(){const s=aea1Hybrid[aea1CurrentSession],d=s.phases[aea1CurrentPhase];document.querySelector('#aea1SessionLabel').textContent=s.label;document.querySelector('#aea1SessionTitle').textContent=s.title;document.querySelector('#aea1HybridContent').innerHTML=`<div class="stage-head"><div><p class="overline">${d.tag}</p><h3>${d.title}</h3></div></div><div class="stage-meta">${d.meta.map(x=>`<span>${x}</span>`).join('')}</div><p class="instruction">${d.intro}</p><ol class="step-list">${d.steps.map(x=>`<li>${x}</li>`).join('')}</ol><div class="lesson-boxes"><div class="lesson-box"><b>Què has de produir?</b><span>${d.deliver}</span></div><div class="lesson-box success"><b>Criteri d’èxit</b><span>${d.success}</span></div></div>`;document.querySelectorAll('[data-aea1-session]').forEach(b=>b.classList.toggle('selected',b.dataset.aea1Session===aea1CurrentSession));document.querySelectorAll('[data-aea1-phase]').forEach(b=>b.classList.toggle('selected',b.dataset.aea1Phase===aea1CurrentPhase));}
document.querySelectorAll('[data-aea1-session]').forEach(b=>b.addEventListener('click',()=>{aea1CurrentSession=b.dataset.aea1Session;aea1CurrentPhase='mission';renderAea1Hybrid();document.querySelector('#aea1HybridContent').focus()}));
document.querySelectorAll('[data-aea1-phase]').forEach(b=>b.addEventListener('click',()=>{aea1CurrentPhase=b.dataset.aea1Phase;renderAea1Hybrid();document.querySelector('#aea1HybridContent').focus()}));
renderAea1Hybrid();

